<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,allPages,fmt} from '../api'
import {useWorkspace} from '../store'
import Icon from '../components/Icon.vue'
const router=useRouter()
async function connect(item:any,type='connection'){const {data}=await api.post('jobs/',{project:store.projectId,kind:type,name:'连接测试 · '+item.name,mode:'live',payload:{resource_id:item.id}});router.push('/tasks/'+data.id)}
const store=useWorkspace(),route=useRoute(),kind=computed(()=>String(route.params.kind)),names:Record<string,string>={model:'模型',skill:'Skill',mcp:'MCP 服务',agent:'Agent'},icons:Record<string,string>={model:'Connection',skill:'MagicStick',mcp:'Link',agent:'Cpu'}
const items=ref<any[]>([]),total=ref(0),page=ref(1),search=ref(''),loading=ref(false),dialog=ref(false),saving=ref(false),form=ref<any>({}),resources=ref<any[]>([])
const applyDialog=ref(false),applyResource=ref<any>(),applyProjectIds=ref<number[]>([]),applying=ref(false)
const writableProjects=computed(()=>store.projects.filter(project=>project.id!==store.projectId&&['owner','editor'].includes(project.role)))
const decisionDialog=ref(false),decisionResource=ref<any>(),decisionState=ref(''),decisionQuestions=ref(JSON.stringify({page_ready:{type:'noul',instructions:'页面是否已准备好接受输入？',criteria:{true:'页面已就绪',false:'页面未就绪'}},next_action:{type:'choice',instructions:'选择下一步安全操作。',criteria:{focus_username:'聚焦账号输入框',stop:'停止并交由人工处理'}}},null,2)),decisionSubmitting=ref(false)
let version=0
async function load(){if(!store.projectId)return;const v=++version;loading.value=true;try{const {data}=await api.get('resources/',{params:{project:store.projectId,kind:kind.value,page:page.value,search:search.value}});if(v===version){items.value=data.results;total.value=data.count}}finally{if(v===version)loading.value=false}}
function filter(){page.value=1;load()}
watch(()=>[kind.value,store.projectId],()=>{page.value=1;dialog.value=false;load()},{immediate:true})
async function edit(item?:any){form.value=item?JSON.parse(JSON.stringify(item)):{name:'',description:'',endpoint:'',enabled:true,settings:{resource_ids:[],instructions:'',model_name:'',provider_type:'openai_compatible'}};form.value.settings||={};form.value.settings.provider_type||='openai_compatible';form.value.secret='';form.value.clear_secret=false;if(kind.value==='agent')resources.value=(await allPages('resources/',{project:store.projectId})).filter(r=>r.kind!=='agent');dialog.value=true}
function chooseProvider(provider:string){form.value.settings.provider_type=provider;if(provider==='h2o_decisions'){form.value.endpoint='http://192.168.5.195:18741';form.value.settings.model_name='h2oai/h2o-lightning-4b';form.value.secret='';form.value.clear_secret=Boolean(form.value.has_secret)}}
function openDecision(item:any){decisionResource.value=item;decisionState.value='登录页面；账号和密码输入框均可见。';decisionQuestions.value=JSON.stringify({page_ready:{type:'noul',instructions:'页面是否已准备好接受输入？',criteria:{true:'页面已就绪',false:'页面未就绪'}},next_action:{type:'choice',instructions:'选择下一步安全操作。',criteria:{focus_username:'聚焦账号输入框',focus_password:'聚焦密码输入框',stop:'停止并交由人工处理'}}},null,2);decisionDialog.value=true}
async function submitDecision(){let questions:any;try{questions=JSON.parse(decisionQuestions.value)}catch{ElMessage.warning('问题定义必须是有效 JSON');return}if(!decisionState.value.trim()){ElMessage.warning('请填写决策上下文');return}decisionSubmitting.value=true;try{const {data}=await api.post('jobs/',{project:store.projectId,kind:'decision',name:'H2O 结构化决策 · '+decisionResource.value.name,mode:'live',payload:{resource_id:decisionResource.value.id,state:decisionState.value,questions}});decisionDialog.value=false;router.push('/tasks/'+data.id)}catch{}finally{decisionSubmitting.value=false}}
async function save(){if(!form.value.name.trim()){ElMessage.warning('请填写名称');return}saving.value=true;try{const payload:any={project:store.projectId,kind:kind.value,name:form.value.name,description:form.value.description,endpoint:form.value.endpoint,enabled:form.value.enabled,settings:form.value.settings};if(form.value.secret||form.value.clear_secret)payload.secret=form.value.secret;await(form.value.id?api.patch(`resources/${form.value.id}/`,payload):api.post('resources/',payload));dialog.value=false;ElMessage.success('配置已保存');await load()}finally{saving.value=false}}
function openApply(item:any){applyResource.value=item;applyProjectIds.value=[];applyDialog.value=true}
async function applyToProjects(){if(!applyProjectIds.value.length){ElMessage.warning('请选择至少一个目标项目');return}applying.value=true;try{const {data}=await api.post(`resources/${applyResource.value.id}/apply-to-projects/`,{project_ids:applyProjectIds.value});const created=data.results.reduce((sum:number,result:any)=>sum+result.created_count,0);const reused=data.results.filter((result:any)=>!result.created).length;ElMessage.success(`已应用到 ${data.results.length} 个项目，新增 ${created} 项能力${reused?`，复用了 ${reused} 项同名配置`:''}`);applyDialog.value=false}catch{}finally{applying.value=false}}
async function remove(item:any){try{await ElMessageBox.confirm(`确认删除「${item.name}」？`,'删除配置',{type:'warning'})}catch{return}await api.delete(`resources/${item.id}/`);if(items.value.length===1&&page.value>1)page.value--;load()}
</script>
<template><div><div class="page-heading"><div><div class="heading-eyebrow">INTELLIGENCE HUB</div><h1>{{names[kind]}}管理<span class="heading-tag">{{total}}</span></h1><p>{{ $t('集中配置团队的智能能力，为测试工作流提供可复用的资源。') }}</p></div><el-button v-if="store.canEdit" type="primary" @click="edit()"><Icon name="Plus"/>添加{{names[kind]}}</el-button></div><div class="simulation-banner"><Icon name="InfoFilled" :size="18"/><div><strong>{{ $t('模型与工具连接') }}</strong><span>{{ $t('支持 OpenAI 兼容模型与 Streamable HTTP MCP。连接测试后显示已验证；真实调用需目标白名单，工具调用须审批。') }}</span></div><span class="mode-pill">CONTROLLED ACCESS</span></div><div class="resource-toolbar"><h3>全部{{names[kind]}} <span class="count-badge">{{total}}</span></h3><div class="inline-actions"><el-input v-model="search" :placeholder="$t('搜索资源名称')" clearable @keyup.enter="filter" @clear="filter"><template #prefix><Icon name="Search" :size="16"/></template></el-input><el-button @click="filter">{{ $t('查询') }}</el-button></div></div>
 <div v-loading="loading" class="resource-cards"><article v-for="item in items" :key="item.id" class="resource-card"><div class="resource-card-top"><span class="large-icon violet"><Icon :name="icons[kind]" :size="27"/></span><span class="status" :class="item.enabled?'ready':'archived'"><i></i>{{item.enabled?'已启用':'已停用'}}</span></div><h3>{{item.name}}</h3><p class="resource-description">{{item.description||'暂无描述'}}</p><div class="resource-tags"><span class="mode-pill">{{item.mode==='live'?'连接已验证':'未验证 / 模拟'}}</span><span v-if="kind==='model'&&item.settings.provider_type==='h2o_decisions'" class="mini-badge">H2O Decisions</span><span v-if="item.has_secret" class="mini-badge"><Icon name="Lock" :size="11"/>{{kind==='model'?'API Key 已加密':$t('密钥已加密')}}</span><span v-if="kind==='agent'" class="mini-badge">{{item.settings.resource_ids?.length||0}} 项关联能力</span></div><div class="resource-meta">更新于 {{fmt(item.updated_at)}}</div><div class="resource-card-footer"><el-button link type="primary" @click="edit(item)">{{store.canEdit?'管理配置':'查看配置'}} <Icon name="ArrowRight" :size="12"/></el-button><el-button v-if="store.canEdit&&writableProjects.length" link type="primary" @click="openApply(item)">应用到其他项目</el-button><el-button v-if="store.canEdit&&kind==='skill'&&item.name==='ui-testcase-generation'&&item.enabled" link type="primary" @click="router.push(`/ai?operation=design&target=ui_case&skill=${item.id}`)">使用 Skill 生成用例</el-button><el-dropdown v-if="store.canEdit&&['model','mcp'].includes(kind)"><el-button link>{{ $t('连接测试') }}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="connect(item)">{{ $t('模型 / MCP 连接') }}</el-dropdown-item><el-dropdown-item v-if="kind==='model'&&item.settings.provider_type==='h2o_decisions'" @click="openDecision(item)">结构化决策测试</el-dropdown-item><el-dropdown-item v-if="kind==='model'&&item.settings.provider_type!=='h2o_decisions'" @click="connect(item,'embed_test')">{{ $t('嵌入模型') }}</el-dropdown-item><el-dropdown-item v-if="kind==='model'&&item.settings.provider_type!=='h2o_decisions'" @click="connect(item,'rerank_test')">Reranker</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="store.canEdit" link @click="remove(item)"><Icon name="Delete" :size="16"/></el-button></div></article><button v-if="store.canEdit" class="resource-create" @click="edit()"><span>+</span><strong>添加{{names[kind]}}</strong><p>{{ $t('扩展你的智能测试能力') }}</p></button></div><el-empty v-if="!loading&&!items.length&&!store.canEdit" :description="$t('暂无资源')"/><div class="pagination"><span>共 {{total}} 项资源</span><el-pagination v-model:current-page="page" :total="total" :page-size="10" layout="prev, pager, next" @current-change="load"/></div>
 <el-dialog v-model="applyDialog" :title="`应用${names[kind]}到其他项目`" width="540px" :close-on-click-modal="false"><p>选择要复制配置的目标项目。目标项目中已存在同名同类型配置时会复用该配置，不会覆盖其内容。Agent 会同时复制关联的模型、Skill 和 MCP；密钥在服务端以加密值复制。</p><el-form label-position="top"><el-form-item label="目标项目"><el-select v-model="applyProjectIds" multiple filterable collapse-tags collapse-tags-tooltip placeholder="选择一个或多个项目" style="width:100%"><el-option v-for="project in writableProjects" :key="project.id" :label="project.name" :value="project.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="applyDialog=false">取消</el-button><el-button type="primary" :loading="applying" :disabled="!applyProjectIds.length" @click="applyToProjects">应用配置</el-button></template></el-dialog><el-dialog v-model="decisionDialog" title="H2O Lightning 结构化决策测试" width="min(760px, 94vw)" :close-on-click-modal="false"><p class="helper">服务只返回分类、概率或分级，不生成自由文本。问题采用文档规定的 systemone 格式，结果会保存为后台任务记录。请勿提交密码、访问令牌或个人敏感信息。</p><el-form label-position="top"><el-form-item label="决策上下文（文本或 JSON）"><el-input v-model="decisionState" type="textarea" :rows="4" maxlength="30000" show-word-limit/></el-form-item><el-form-item label="命名问题 JSON"><el-input v-model="decisionQuestions" type="textarea" :rows="13" class="code-input"/></el-form-item></el-form><template #footer><el-button @click="decisionDialog=false">取消</el-button><el-button type="primary" :loading="decisionSubmitting" @click="submitDecision">提交真实决策任务</el-button></template></el-dialog>
</div></template>
